template:
use std::sync::atomic::AtomicI32;
use std::sync::atomic::Ordering;

fn update(val: &AtomicI32) -> bool {
    let current = val.load(Ordering::Relaxed);
    let result = val.⟦method⟧(
        current,
        current + 10,
        Ordering::Relaxed,
        Ordering::Relaxed,
    );
    result.⟦check⟧
}

fn main() {
    let a = AtomicI32::new(5);
    assert!(update(&a));
    assert_eq!(a.load(Ordering::Relaxed), 15);
}
